import torch
import triton
import triton.language as tl


@triton.jit
def _tanh(x):
    # overflow-safe tanh built only from tl.exp/tl.abs/tl.where (no tl.sigmoid)
    ax = tl.abs(x)
    e = tl.exp(-2.0 * ax)
    t = (1.0 - e) / (1.0 + e)
    return tl.where(x >= 0, t, -t)

